contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 priorDelay) public payable {
        require(address(this).balance >= amount);
        require(priorDelay > 0);

        // Setup: ensure c has a pastBlockTime strictly less than the current block.timestamp
        // by advancing time with an intermediate successful fallback call.
        uint256 preTimestamp = block.timestamp;
        bool setupOk = false;
        if (amount >= 10 ether) {
            // If the incoming amount itself can be used for setup, do it once.
            // But we need a distinct deciding call, so we make setup with the same amount.
            // To guarantee strict timestamps, we rely on the caller providing different blocks.
            // Use a dummy call only if c has no pastBlockTime yet (initial value 0).
            (bool successSetup, ) = address(c).call{value: amount}("");
            setupOk = successSetup;
        }

        // Read the before state through the public getter.
        uint256 beforeTime = c.pastBlockTime();

        // Deciding call: attempt the fallback with the given amount.
        bool reverted;
        if (amount >= 10 ether) {
            (bool success, ) = address(c).call{value: amount}("");
            reverted = !success;
        } else {
            // Insufficient value must revert.
            (bool success, ) = address(c).call{value: amount}("");
            reverted = !success;
        }

        // Read the after state.
        uint256 afterTime = c.pastBlockTime();

        // The general rule:
        //  - With amount >= 10 ether and block.timestamp > beforeTime, the call succeeds
        //    and updates pastBlockTime to the current block.timestamp.
        //  - With amount < 10 ether, the call reverts and pastBlockTime remains unchanged.
        if (amount >= 10 ether) {
            if (block.timestamp > beforeTime) {
                assert(!reverted && afterTime == block.timestamp);
            } else {
                assert(reverted && afterTime == beforeTime);
            }
        } else {
            assert(reverted && afterTime == beforeTime);
        }
    }

    receive() external payable {}
}

