contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint seed) public payable {
        require(seed >= 1, "seed must be at least 1");
        require(address(this).balance >= 10 ether, "insufficient balance");

        // Ensure we are on an even block number (or odd) to collide with the 15 divisor behavior.
        // The property is only about revert/success depending on block.number % 15 == 0.
        uint initialPastBlockTime = c.pastBlockTime();
        address cAddress = address(c);
        uint cBalanceBefore = cAddress.balance;
        uint thisBalanceBefore = address(this).balance;

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalPastBlockTime = c.pastBlockTime();
        uint cBalanceAfter = cAddress.balance;
        uint thisBalanceAfter = address(this).balance;

        // Determine if the call should have succeeded based on the block.number condition.
        // block.number % 15 == 0 means the contract should revert (because of the timestamp update before the transfer? Actually contract does not revert explicitly, but the property test must be general.)
