        // with exactly 10 ether.

        // Record the before state.
        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeBal = address(c).balance;

        // The deciding call. Use any amount; the contract requires exactly 10 ether,
        // so provide 10 ether. dt is unused for the call itself but keeps the
