            // Strictly increasing timestamp means the call must not revert and must
            // update pastBlockTime to the current timestamp, preserving/raising balance.
            assert(!reverted);
            assert(afterTime == block.timestamp);
            assert(afterBal == beforeBal + 10 ether || afterBal == 0);
        } else {
            // Timestamp not strictly greater: the call must revert and leave state untouched.
            assert(reverted);
            assert(afterTime == beforeTime);
            assert(afterBal == beforeBal);
        }
    }

    receive() external payable {}
}

