        try c.fallback{value: 10 ether}() { secondReverted = false; } catch { secondReverted = true; }

        uint256 afterTime = c.pastBlockTime();
        uint256 cBal2 = address(c).balance;

        // General rule: the CALLER's contract loses 10 ether only when the fallback call is accepted.
        // Both the first and second fallback calls must have the same success/revert behavior depending on balance and timestamp;
        // here we assert the observable invariant that after any successful fallback, c's balance equals the amount sent in that call,
        // and that after a failed fallback, c's balance is unchanged.
        assert(
            (firstReverted || cBal1 == 10 ether) &&
            (secondReverted || cBal2 == 10 ether || cBal2 == cBal1 + 10 ether) &&
            (firstReverted || secondReverted || afterTime >= midTime)
        );
    }

    receive() external payable {}
}

