    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint timeDelta) public payable {
        require(amount <= address(this).balance);

        uint beforeTime = c.pastBlockTime();

        // Ensure the fallback call itself cannot return early via the timestamp guard
        // when we intend to test the success path: timeDelta > 0 and block.timestamp > beforeTime.
        // For the revert path, amount is wrong, so the timestamp guard cannot make the call succeed.
        require(timeDelta > 0);
        require(block.timestamp > beforeTime);
        require(block.timestamp >= timeDelta);

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();

        // General rule: the fallback completes iff amount == 10 ether; if it completes,
        // pastBlockTime advances to the current block timestamp; if it reverts, pastBlockTime is unchanged.
        assert(
            (reverted == (amount != 10 ether)) &&
            (reverted ? afterTime == beforeTime : afterTime == block.timestamp)
        );
    }

    receive() external payable {}
}

