    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint firstTime, uint secondTime) public payable {
        require(firstTime > 0 && secondTime > 0);

        // Explicit type; helps the solver treat these as arbitrary timestamps.
        uint tBefore;
        uint vFirst;
        uint vSecond;

        // Price the setup call.
        uint amountFirst = 10 ether;
        uint amountSecond = 10 ether;

        // We need to fund this contract to make the calls.
        require(address(this).balance >= amountFirst || address(this).balance >= amountSecond);

        // First call: drive c through its fallback with 10 ether.
        // If the current time is not > pastBlockTime (initially 0), this will revert.
        // We use a low-level call so that we can catch the revert status.
        (bool okFirst, ) = address(c).call{value: amountFirst}("");
        tBefore = c.pastBlockTime();
        vFirst = okFirst ? 1 : 0;

        // Second call: drive c's fallback again with 10 ether. This is the deciding call.
        // Its success depends on whether its timestamp exceeds the pastBlockTime after the first call.
        (bool okSecond, ) = address(c).call{value: amountSecond}("");
        vSecond = okSecond ? 1 : 0;

        uint tAfter = c.pastBlockTime();
        uint cBal = address(c).balance;
        uint thisBal = address(this).balance;

        // General rule: the second call succeeds iff block.timestamp > pastBlockTime before that call.
        // (For the test, the value is encoded by the bool return of the low-level call.)
        // Since we cannot read block.timestamp directly, we observe its effect through pastBlockTime.
        // If the second call succeeds, pastBlockTime must have been updated to block.timestamp,
        // and the contract balance must be at least the second amount (plus any prior balance).
        // If it fails, no state change occurs (aside from possible revert side-effects).
        assert(
            (vSecond == 1) == (tAfter == block.timestamp) &&
            (vSecond == 1 || tAfter == tBefore) &&
            (vSecond == 0 || cBal >= amountSecond) &&
            (vSecond == 1 || thisBal >= amountSecond || okFirst == false)
        );
    }
}

