        // The contract starts with pastBlockTime == 0, so block.timestamp > 0 is always true initially.
        // To test the revert case, we must first consume the fallback with a successful call,
        // then attempt a second call at the same or earlier timestamp. We cannot control block.timestamp,
        // but we can ensure the first call succeeds (pastBlockTime starts at 0), then a second call
        // in the same transaction will have the same block.timestamp and thus revert because
        // block.timestamp > pastBlockTime is false.

        // First call: should succeed, setting pastBlockTime = block.timestamp
        (bool success1, ) = address(c).call{value: amount}(callData);

        // Determine the revert condition for the first call:
        // it reverts if msg.value != 10 ether
        // otherwise it succeeds and sets pastBlockTime = block.timestamp
        bool expectedRevert1 = (amount != 10 ether);

        // Second call: should revert because block.timestamp == pastBlockTime (not strictly greater)
        (bool success2, ) = address(c).call{value: amount}(callData);

        // General rule: a fallback call reverts exactly when either it does not send exactly 10 ether,
        // or the current timestamp is not strictly greater than pastBlockTime before the call.
        // For the first call, pastBlockTime == 0, so the timestamp condition holds (assuming block.timestamp > 0).
        // For the second call, pastBlockTime == block.timestamp (from the first call), so the condition fails.
        // Thus:
        // success1 == (amount == 10 ether) and success2 == false (since amount == 10 ether would still revert on timestamp).
