contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint timeAdvance) public payable {
        require(address(this).balance >= amount);

        // First fallback call to establish a fresh state.
        uint before1 = c.pastBlockTime();
        bool reverted1 = false;
        try c.fallback{value: amount}() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        uint after1 = c.pastBlockTime();

        // The deciding call: same visible-value semantics, but with a strictly later timestamp.
        // Since we cannot directly advance block.timestamp, we rely on the rule that
        // when the caller sends exactly 10 ether and the current timestamp is already
        // greater than the stored one, the call must succeed and update pastBlockTime
        // to the current block.timestamp. The first call establishes a stored timestamp
        // that is at most the current block.timestamp (because it was set to it on success),
        // and since block.timestamp cannot decrease within a transaction, the second
        // call has timestamp >= after1, and must therefore succeed as long as
        // block.timestamp > after1 (which is true unless after1 is exactly now and
        // the first call already succeeded with the same second; this does not
        // invalidate the general invariant about success/failure being controlled
        // solely by msg.value and timestamp).
        //
        // To preserve generality and not depend on increasing timestamps within
        // the same transaction, we assert the disjunction that exactly mirrors
        // the contract's own require logic:
        // a call completes iff msg.value == 10 ether AND block.timestamp > pastBlockTime.
        // We evaluate this for the second call.
        uint before2 = c.pastBlockTime();
        bool reverted2 = false;
        try c.fallback{value: amount}() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint after2 = c.pastBlockTime();

        // The rule: the second fallback call reverts exactly when the sent amount
        // is not 10 ether OR the current block.timestamp is not strictly greater
        // than the value of pastBlockTime observed immediately before the call.
        // If it does not revert, then pastBlockTime must have been updated to the
        // current block.timestamp, which equals after2, and must be >= before2.
        // This is a general statement about the contract's public behavior.
        assert(
            (
                reverted2 == (amount != 10 ether || block.timestamp <= before2)
            )
            &&
            (
                reverted2 || after2 == block.timestamp
            )
        );
    }

    receive() external payable {}
}

