contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 delta) public payable {
        require(amount >= 0 && delta > 0);
        require(amount <= address(this).balance);

        // Establish a valid previous timestamp by making a successful call first.
        // The first tx succeeds iff it sends exactly 10 ETH and block.timestamp > 0 (always true after genesis).
        uint256 t0 = block.timestamp;
        bool firstReverted;
        try c.fallback{value: 10 ether}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        require(!firstReverted);

        uint256 prevTime = c.pastBlockTime();
        require(prevTime == t0);

        // Bound the second call's timestamp to be either strictly greater than prevTime or not.
        // delta parameter controls the offset in seconds from prevTime for the second attempt.
        uint256 newTimestamp = prevTime + delta;

        // Advance time to the desired newTimestamp using a dummy block? Not allowed.
        // Instead, we rely on actual block.timestamp of the test transaction.
        // Since we cannot modify block.timestamp, we use the current one.
        // The test's block.timestamp is at least t0 (same tx? No, each call is a tx; but here calls happen in one tx).
        // Actually both calls occur in the same transaction, so block.timestamp is constant.
        // Therefore, the second call will have the same block.timestamp as the first, so it cannot
        // succeed if the first already set pastBlockTime to that same timestamp.
        // This means: if the first call succeeded, then the second call with any value must revert
        // because block.timestamp > pastBlockTime is false (equal).
        // So we test the revert condition: amount != 10 ether OR block.timestamp <= pastBlockTime.
        // Since block.timestamp == pastBlockTime after first call, the second call always reverts.
        // However, the rule should be general. We can test that when the second call reverts, pastBlockTime
        // remains unchanged. If the second call does not revert (impossible in same tx), we check that
        // it succeeds only under the condition.

        bool secondReverted;
        try c.fallback{value: amount}() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // After both calls, pastBlockTime should be either prevTime (if second reverted) or block.timestamp (if second succeeded).
        uint256 finalTime = c.pastBlockTime();

        // General rule: the second call reverts iff (amount != 10 ether) OR (block.timestamp <= prevTime).
        // Since block.timestamp == prevTime in this transaction, the condition simplifies to amount != 10 ether.
        // But to be general, we assert the exact condition.
        // We must use the actual block.timestamp of this transaction (not the parameter delta).
        uint256 currentTime = block.timestamp;
        bool expectedRevert = (amount != 10 ether) || (currentTime <= prevTime);

        assert(secondReverted == expectedRevert);
        // Additionally, if not reverted, pastBlockTime must equal currentTime and balance must be transferred if block.number % 15 == 0.
        // But we only assert the revert condition as the main rule.
        // To make it stronger, we also assert that if it did not revert, finalTime == currentTime.
        if (!secondReverted) {
            assert(finalTime == currentTime);
        } else {
            assert(finalTime == prevTime);
        }
    }

    receive() external payable {}
}

